using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: DateTime.UtcNow is no longer evaluated client-side
        // in HasData; use a fixed value instead to produce deterministic migrations.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking-change fixes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "CatalogDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);

            // EF Core 9 breaking change: Cosmos provider now uses "$type" instead of
            // "Discriminator" for the discriminator property. For existing documents
            // that already store "Discriminator", explicitly configure the old name.
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public string Category { get; set; } = null!;
}

// Example showing the sync → async migration required by EF Core 9 Cosmos provider.
// EF Core 9 breaking change: Synchronous I/O is no longer supported for Cosmos.
// All queries/saves must use async methods (ToListAsync, SaveChangesAsync, etc.).
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 – now throws InvalidOperationException in EF Core 9):
    //   var products = _db.Products.Where(p => p.Category == category).ToList();

    // AFTER (EF Core 9 fix – use async):
    public async Task<List<Product>> GetByCategoryAsync(string category)
        => await _db.Products.Where(p => p.Category == category).ToListAsync();
}

